export function VersionHistory({
  fileName = "{{fileName}}",
  rows = "{{rows}}",
  showAuthor = {{showAuthor}},
  accent = "{{accent}}",
}) {
  const versions = [
    { label: "Current version", author: "Priya Shah", time: "2026-08-14T10:20", display: "Today, 10:20am", current: true },
    { label: "Version 2", author: "Sam Ortiz", time: "2026-08-12T15:00", display: "12 Aug, 3:00pm", current: false },
    { label: "Version 1", author: "Priya Shah", time: "2026-08-09T09:15", display: "9 Aug, 9:15am", current: false },
  ].slice(0, Number(rows));
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 320, padding: "16px 18px", borderRadius: 12, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700, fontSize: 12, textTransform: "uppercase", letterSpacing: ".03em", color: "#24143099" }}>Version history &middot; {fileName}</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {versions.map((v, i) => (
          <li key={v.label} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: i < versions.length - 1 ? "1px solid #24143012" : "none" }}>
            <span style={{ flex: "none", width: 9, height: 9, borderRadius: 999, background: v.current ? accent : "#24143030" }} />
            <div>
              <p style={{ margin: 0, fontWeight: 600 }}>{v.label}{showAuthor ? ` · ${v.author}` : ""}</p>
              <p style={{ margin: "1px 0 0", fontSize: 11, color: "#24143088" }}><time dateTime={v.time}>{v.display}</time></p>
            </div>
            {!v.current && <button type="button" style={{ marginLeft: "auto", flex: "none", border: "1.5px solid #24143030", background: "none", borderRadius: 7, padding: "5px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>Restore</button>}
          </li>
        ))}
      </ul>
    </div>
  );
}
